const cloneIR = v => {
  if (Array.isArray(v)) {
    const a = new Array(v.length);
    for (let i = 0; i < v.length; i++) a[i] = cloneIR(v[i]);
    return a;
  }
  if (v !== null && typeof v === 'object') {
    const o = {};
    for (const k in v) o[k] = cloneIR(v[k]);
    return o;
  }
  return v;
};

// b(data) decodes a compressed IR body the first time it is read, then hands out a copy per read.
const b = data => {
  let tree;
  const out = h => {
    if (tree === undefined) tree = unflatten({ tokens: huffDecode(data), i: 0 });
    return walk(cloneIR(tree), h);
  };
  out.precompiled = true;
  return out;
};

